import { Component } from '@angular/core';
import { EtapaJudicial } from '../../../models/etapa.judicial';
import { EtapaJudicialService } from '../../../controllers/etapa.judicial.service';
import { ActivatedRoute } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { AutocompleteFieldComponent } from "../../../shared/generic-form/autocomplete-field/autocomplete-field.component";

@Component({
    selector: 'app-form-etapas-judiciales',
    imports: [
        FormsModule,
        AutocompleteFieldComponent
    ],
    templateUrl: './form-etapas-judiciales.component.html',
    styleUrl: './form-etapas-judiciales.component.css'
})
export class FormEtapasJudicialesComponent {
  edit:EtapaJudicial={
    nombre: '',
    proceso_judicial_id: 0,
    id: 0,
    deleted_at: null,
    created_at: '',
    updated_at: null
  }

  constructor(
    public etapaController:EtapaJudicialService,
    private route:ActivatedRoute,
  ){}

  ngOnInit(){
    this.route.params.subscribe(async (params) => {
      if(params['etapa_id']){
        this.edit = (await this.etapaController.find(params['etapa_id']))!
      }
    })
  }

  public async save(){
    const res = await this.etapaController.createOrUpdate(this.edit)
    if(res){
      this.edit= res
    }
  }
}
